  "physio": {
    "intro": "CalCup runs a professional on-site physiotherapy and recovery station across all three days, staffed by licensed chiropractors and physical therapists caring for every athlete — men's and women's divisions alike.",
    "lead": {
      "org": "Vibrant Niche Chiropractic",
      "tagline": "Chiropractic, Massage &amp; Pilates · Redwood City",
      "desc": "Led by Dr. Anja Huq, Vibrant Niche takes athletes from pain to peak performance — combining chiropractic, massage therapy and Pilates to treat musculoskeletal pain at its root and restore mobility.",
      "logo": "https://vibrantniche.com/wp-content/uploads/2024/03/VN_nameplate_wideWHTborder_360.png",
      "website": "https://vibrantniche.com",
      "email": "office@vibrantniche.com",
      "address": "505 Seaport Court, Suite 103, Redwood City, CA 94063",
      "phone": "(650) 260-4655"
    },
    "team": [
      {
        "name": "Dr. Anja Huq",
        "org": "Vibrant Niche — Chiropractic & Massage",
        "role": "Physiotherapy lead"
      },
      {
        "name": "Dr. Sue Bedi",
        "org": "Vibrant Niche — Chiropractic & Massage",
        "role": ""
      },
      {
        "name": "Dr. Marisa Chu",
        "org": "Vibrant Niche — Chiropractic & Massage",
        "role": ""
      },
      {
        "name": "Dr. Merick Dang",
        "org": "Vibrant Niche — Chiropractic & Massage",
        "role": ""
      }
    ],
    "protocols": [
      "Dedicated courtside treatment area for taping, soft-tissue work and recovery, open throughout the event.",
      "Concussion protocol (SCAT6): any suspected concussion is removed from play and evaluated — no same-day return after a confirmed or suspected concussion.",
      "Supplies (tape, Biofreeze, ice) stocked from a pre-tournament inventory and replenished daily.",
      "Safety always overrides competition."
    ],
    "recovery": {
      "intro": "Four games in three days is a real test. You don't need the science — you need a simple routine you actually follow. Here's what the pros do between games.",
      "tips": [
        {
          "icon": "ti-bolt",
          "title": "Refuel in the first hour",
          "body": "The 30–60 minutes after a game is your window — take on carbs + protein: chocolate milk, a turkey sandwich, Greek yogurt with fruit, or a banana. Short gap before the next game? Keep it light: fruit and a sports drink."
        },
        {
          "icon": "ti-droplet",
          "title": "Drink to the colour",
          "body": "Aim for pale-yellow urine. For every pound lost during a game, drink 16–24 oz to rehydrate. Sip steadily between games — don't chug right before you step on court."
        },
        {
          "icon": "ti-run",
          "title": "Warm up — every game",
          "body": "Even game four. Five to eight minutes: light jog, leg swings, arm circles, then a few throws building to full pace. Cold muscles are how you tweak a hamstring on day two."
        },
        {
          "icon": "ti-stretching",
          "title": "Move before you sit",
          "body": "After the whistle, keep moving 5–10 minutes (easy walk or bike) before you sit down, then some light mobility for hips, shoulders and back. Save the deep static stretching for the end of the day."
        },
        {
          "icon": "ti-moon",
          "title": "Sleep is the cheat code",
          "body": "Eight to nine hours does more than any supplement. Poor sleep means slower reactions and higher injury risk on back-to-back days — protect it like part of your training."
        }
      ],
      "sources": [
        {
          "name": "TrueSport — Recovery during tournaments",
          "url": "https://truesport.org/preparation-recovery/recovery-during-sports-tournaments/"
        },
        {
          "name": "Gatorade Sports Science Institute — Recovery techniques",
          "url": "https://www.gssiweb.org/sports-science-exchange/article/sse-120-recovery-techniques-for-athletes"
        },
        {
          "name": "Memorial Hermann — Refueling after competition",
          "url": "https://memorialhermann.org/services/specialties/rockets-sports-medicine-institute/sports-nutrition/7-rules-for-refueling-after-a-tournament"
        }
      ]
    }
  },
